1	package api
2	
3	// Concurrent regression tests for the public HTTP surface. Unlike the store
4	// level concurrency test, these drive a real HTTP server (one service instance
5	// backed by a healthy on-disk SQLite store) through POST /v1/net-policies and
6	// GET /v1/net-policies so the assertions cover the externally visible results:
7	// status codes, response bodies, ordering and the published error shape.
8	
9	import (
10		"encoding/json"
11		"io"
12		"net/http"
13		"net/http/httptest"
14		"path/filepath"
15		"reflect"
16		"runtime"
17		"strings"
18		"sync"
19		"testing"
20		"time"
21	
22		"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
23	)
24	
25	const clientTimeout = 10 * time.Second
26	
27	const (
28		raceNamespace = "payments"
29		raceName      = "race-policy"
30		raceLabel     = "tier=backend"
31	)
32	
33	// The two racing groups are identical except for one legal plugin string value
34	// ("mode"); "zone" and the rules stay identical across the groups.
35	const raceBodyA = `{
36		"namespace": "payments",
37		"name": "race-policy",
38		"label": "tier=backend",
39		"rules": [{"direction": "ingress", "action": "deny", "ports": [80, 100]}],
40		"pluginParams": {"mode": "enforce", "zone": "east"}
41	}`
42	
43	// Equivalent content for group A: top-level members, rule members and
44	// pluginParams members all appear in a different order.
45	const raceBodyAReordered = `{
46		"pluginParams": {"zone": "east", "mode": "enforce"},
47		"rules": [{"ports": [80, 100], "action": "deny", "direction": "ingress"}],
48		"label": "tier=backend",
49		"name": "race-policy",
50		"namespace": "payments"
51	}`
52	
53	const raceBodyB = `{
54		"namespace": "payments",
55		"name": "race-policy",
56		"label": "tier=backend",
57		"rules": [{"direction": "ingress", "action": "deny", "ports": [80, 100]}],
58		"pluginParams": {"mode": "audit", "zone": "east"}
59	}`
60	
61	// Equivalent content for group B with object members reordered.
62	const raceBodyBReordered = `{
63		"pluginParams": {"zone": "east", "mode": "audit"},
64		"rules": [{"ports": [80, 100], "action": "deny", "direction": "ingress"}],
65		"label": "tier=backend",
66		"name": "race-policy",
67		"namespace": "payments"
68	}`
69	
70	// Same identity with a null plugin member racing with the legal submissions:
71	// always invalid input, regardless of how far the other requests have got.
72	const raceBodyNullMember = `{
73		"namespace": "payments",
74		"name": "race-policy",
75		"label": "tier=backend",
76		"rules": [{"direction": "ingress", "action": "deny", "ports": [80, 100]}],
77		"pluginParams": {"zone": "east", "mode": null}
78	}`
79	
80	type postOutcome struct {
81		kind   string // "A", "B" or "null"
82		status int
83		body   []byte
84		err    error
85	}
86	
87	type queryObservation struct {
88		target string
89		status int
90		body   []byte
91		err    error
92	}
93	
94	// newConcurrentTestServer starts a real HTTP server backed by a fresh SQLite
95	// file so concurrent clients exercise the genuinely published entry points.
96	func newConcurrentTestServer(t *testing.T) (*httptest.Server, *store.Store) {
97		t.Helper()
98		st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
99		if err != nil {
100			t.Fatalf("open: %v", err)
101		}
102		server := httptest.NewServer(NewRouter(st))
103		t.Cleanup(func() {
104			server.Close()
105			st.Close()
106		})
107		return server, st
108	}
109	
110	func clientRequest(client *http.Client, method, target, body string) (int, []byte, error) {
111		var reader io.Reader
112		if body != "" {
113			reader = strings.NewReader(body)
114		}
115		req, err := http.NewRequest(method, target, reader)
116		if err != nil {
117			return 0, nil, err
118		}
119		resp, err := client.Do(req)
120		if err != nil {
121			return 0, nil, err
122		}
123		defer resp.Body.Close()
124		raw, err := io.ReadAll(resp.Body)
125		if err != nil {
126			return resp.StatusCode, nil, err
127		}
128		return resp.StatusCode, raw, nil
129	}
130	
131	// assertExactErrorBytes is the []byte counterpart of assertExactErrorShape:
132	// exactly one top-level "error" object holding string code and non-empty
133	// message, with no other members.
134	func assertExactErrorBytes(t *testing.T, status int, raw []byte, wantStatus int, wantCode string) {
135		t.Helper()
136		if status != wantStatus {
137			t.Fatalf("status = %d, want %d: %s", status, wantStatus, string(raw))
138		}
139		var top map[string]json.RawMessage
140		if err := json.Unmarshal(raw, &top); err != nil {
141			t.Fatalf("decode error body: %v", err)
142		}
143		if len(top) != 1 {
144			t.Fatalf("error body has %d top-level keys, want exactly one (error): %s", len(top), string(raw))
145		}
146		errRaw, ok := top["error"]
147		if !ok {
148			t.Fatalf("error body missing top-level error object: %s", string(raw))
149		}
150		var errObj map[string]json.RawMessage
151		if err := json.Unmarshal(errRaw, &errObj); err != nil {
152			t.Fatalf("error member is not an object: %v", err)
153		}
154		if len(errObj) != 2 {
155			t.Fatalf("error object has %d members, want exactly code and message: %s", len(errObj), string(raw))
156		}
157		var code, message string
158		if err := json.Unmarshal(errObj["code"], &code); err != nil {
159			t.Fatalf("error.code is not a string: %s", string(raw))
160		}
161		if err := json.Unmarshal(errObj["message"], &message); err != nil {
162			t.Fatalf("error.message is not a string: %s", string(raw))
163		}
164		if code != wantCode {
165			t.Fatalf("error.code = %q, want %q (body %s)", code, wantCode, string(raw))
166		}
167		if message == "" {
168			t.Fatalf("error.message is empty: %s", string(raw))
169		}
170		for _, leak := range []string{"sql", "sqlite", "goroutine", ".go:", "panic", "/", "\\"} {
171			if strings.Contains(strings.ToLower(message), leak) {
172				t.Fatalf("error.message leaks %q: %s", leak, message)
173			}
174		}
175	}
176	
177	func decodeRecord(t *testing.T, raw []byte) map[string]any {
178		t.Helper()
179		var record map[string]any
180		if err := json.Unmarshal(raw, &record); err != nil {
181			t.Fatalf("decode record %s: %v", string(raw), err)
182		}
183		return record
184	}
185	
186	// Empty store, same namespace and policy name: two content groups differing in
187	// one legal plugin string value race to register, each group including
188	// equivalent submissions with object members reordered, alongside requests
189	// carrying a null plugin member and queries issued during the burst. Exactly
190	// one 201 fixes the winning content; the winning group's other requests return
191	// 200 with that same record, the losing group all 409, and the null requests
192	// all 400. Queries observe either 404 or the single complete winning record.
193	func TestConcurrentHTTPSameIdentityRace(t *testing.T) {
194		// Repeat against fresh databases: the winning group may differ per round.
195		for round := 0; round < 3; round++ {
196			t.Run("round", func(t *testing.T) {
197				server, _ := newConcurrentTestServer(t)
198				client := &http.Client{Timeout: clientTimeout}
199	
200				submissions := []struct {
201					kind string
202					body string
203				}{
204					{"A", raceBodyA},
205					{"A", raceBodyA},
206					{"A", raceBodyAReordered},
207					{"A", raceBodyAReordered},
208					{"B", raceBodyB},
209					{"B", raceBodyB},
210					{"B", raceBodyBReordered},
211					{"B", raceBodyBReordered},
212					{"null", raceBodyNullMember},
213					{"null", raceBodyNullMember},
214				}
215	
216				// Readers start before the writers are released so the empty-store
217				// window is genuinely queried, and keep going until every write
218				// request has returned. Each reader reports after its first
219				// observation; the test releases the writers only after some
220				// readers have queried the still-empty store.
221				stopReaders := make(chan struct{})
222				readerReady := make(chan struct{}, 4)
223				var readers sync.WaitGroup
224				observations := make(chan queryObservation, 65536)
225				queryTargets := []string{
226					server.URL + "/v1/net-policies?namespace=payments",
227					server.URL + "/v1/net-policies?label=tier%3Dbackend",
228				}
229				for i := 0; i < 4; i++ {
230					readers.Add(1)
231					go func(id int) {
232						defer readers.Done()
233						ready := false
234						for attempts := 0; ; attempts++ {
235							select {
236							case <-stopReaders:
237								return
238							default:
239							}
240							target := queryTargets[(id+attempts)%len(queryTargets)]
241							status, body, err := clientRequest(client, http.MethodGet, target, "")
242							select {
243							case observations <- queryObservation{target: target, status: status, body: body, err: err}:
244							default:
245							}
246							if !ready {
247								ready = true
248								readerReady <- struct{}{}
249							}
250							runtime.Gosched()
251						}
252					}(i)
253				}
254				<-readerReady
255				<-readerReady
256	
257				start := make(chan struct{})
258				var writers sync.WaitGroup
259				outcomes := make(chan postOutcome, len(submissions))
260				for _, submission := range submissions {
261					writers.Add(1)
262					go func(submission struct {
263						kind string
264						body string
265					}) {
266						defer writers.Done()
267						<-start
268						status, body, err := clientRequest(client, http.MethodPost,
269							server.URL+"/v1/net-policies", submission.body)
270						outcomes <- postOutcome{kind: submission.kind, status: status, body: body, err: err}
271					}(submission)
272				}
273	
274				close(start)
275				writers.Wait()
276				close(stopReaders)
277				readers.Wait()
278				close(observations)
279	
280				results := make([]postOutcome, 0, len(submissions))
281				for range submissions {
282					results = append(results, <-outcomes)
283				}
284	
285				for _, result := range results {
286					if result.err != nil {
287						t.Fatalf("POST %s failed: %v", result.kind, result.err)
288					}
289				}
290	
291				wantByGroup := map[string]map[string]any{
292					"A": wantRecord(t, raceBodyA, 1, false),
293					"B": wantRecord(t, raceBodyB, 1, false),
294				}
295	
296				// The single 201 response determines the winner; nothing here
297				// prescribes which content wins or relies on arrival order.
298				var winner map[string]any
299				winnerKind := ""
300				created, okStatus, rejected := 0, 0, 0
301				for _, result := range results {
302					switch result.status {
303					case http.StatusCreated:
304						created++
305						winner = decodeRecord(t, result.body)
306					case http.StatusOK:
307						okStatus++
308					case http.StatusConflict:
309					case http.StatusBadRequest:
310						rejected++
311					default:
312						t.Fatalf("unexpected POST status %d: %s", result.status, string(result.body))
313					}
314				}
315				if created != 1 {
316					t.Fatalf("created = %d responses, want exactly one 201", created)
317				}
318				if mode, _ := winner["pluginParams"].(map[string]any)["mode"].(string); mode == "enforce" {
319					winnerKind = "A"
320				} else if mode == "audit" {
321					winnerKind = "B"
322				} else {
323					t.Fatalf("winning record pluginParams.mode = %v, want enforce or audit", winner["pluginParams"])
324				}
325				t.Logf("group %s (mode=%s) won the registration race", winnerKind,
326					winner["pluginParams"].(map[string]any)["mode"])
327				if !reflect.DeepEqual(winner, wantByGroup[winnerKind]) {
328					t.Fatalf("winning record = %v, want the full %s submission with order 1 conflict false",
329						winner, winnerKind)
330				}
331				if winner["order"] != float64(1) || winner["conflict"] != false {
332					t.Fatalf("winner order/conflict = %v/%v, want 1/false", winner["order"], winner["conflict"])
333				}
334	
335				winnerPeers, loserPeers := 0, 0
336				for _, result := range results {
337					switch result.kind {
338					case winnerKind:
339						if result.status == http.StatusCreated {
340							continue
341						}
342						// Remaining requests with the winning content are idempotent
343						// retries: 200 with the same original record.
344						if result.status != http.StatusOK {
345							t.Fatalf("winning group peer status = %d, want 200: %s",
346								result.status, string(result.body))
347						}
348						if got := decodeRecord(t, result.body); !reflect.DeepEqual(got, winner) {
349							t.Fatalf("200 record = %v, want the original winning record %v", got, winner)
350						}
351						winnerPeers++
352					case "null":
353						assertExactErrorBytes(t, result.status, result.body,
354							http.StatusBadRequest, "InvalidNetPolicyInputError")
355					default:
356						// Every request in the other group loses with 409.
357						assertExactErrorBytes(t, result.status, result.body,
358							http.StatusConflict, "NetPolicyConflictError")
359						loserPeers++
360					}
361				}
362				if winnerPeers != 3 {
363					t.Fatalf("winning group 200 peers = %d, want 3", winnerPeers)
364				}
365				if loserPeers != 4 {
366					t.Fatalf("losing group 409 responses = %d, want 4", loserPeers)
367				}
368				if rejected != 2 || okStatus != 3 {
369					t.Fatalf("status counts: 200=%d 400=%d, want 200=3 400=2", okStatus, rejected)
370				}
371	
372				// Queries observed during the race: 404 before anything committed,
373				// or 200 with exactly one complete record — always the eventual
374				// winner, never a duplicate identity, a losing content or a mix.
375				sawNotFound, sawFound := false, false
376				for observation := range observations {
377					if observation.err != nil {
378						t.Fatalf("GET %s failed: %v", observation.target, observation.err)
379					}
380					switch observation.status {
381					case http.StatusNotFound:
382						assertExactErrorBytes(t, observation.status, observation.body,
383							http.StatusNotFound, "NetPolicyNotFoundError")
384						sawNotFound = true
385					case http.StatusOK:
386						var body struct {
387							Items []map[string]any `json:"items"`
388						}
389						if err := json.Unmarshal(observation.body, &body); err != nil {
390							t.Fatalf("decode items: %v", err)
391						}
392						if len(body.Items) != 1 {
393							t.Fatalf("GET %s returned %d items, want exactly one identity: %s",
394								observation.target, len(body.Items), string(observation.body))
395						}
396						if !reflect.DeepEqual(body.Items[0], winner) {
397							t.Fatalf("GET %s item = %v, want the complete winning record %v",
398								observation.target, body.Items[0], winner)
399						}
400						sawFound = true
401					default:
402						t.Fatalf("GET during race status = %d: %s",
403							observation.status, string(observation.body))
404					}
405				}
406				if !sawNotFound {
407					t.Fatalf("no 404 was observed while the registration burst was in flight")
408				}
409				if !sawFound {
410					t.Fatalf("no 200 query was observed while the registration burst was in flight")
411				}
412	
413				// Final state through both filters: only the winner, identical in
414				// every submitted field plus order and conflict.
415				for _, target := range queryTargets {
416					status, body, err := clientRequest(client, http.MethodGet, target, "")
417					if err != nil {
418						t.Fatalf("final GET %s: %v", target, err)
419					}
420					if status != http.StatusOK {
421						t.Fatalf("final GET %s status = %d: %s", target, status, string(body))
422					}
423					var listed struct {
424						Items []map[string]any `json:"items"`
425					}
426					if err := json.Unmarshal(body, &listed); err != nil {
427						t.Fatalf("decode final items: %v", err)
428					}
429					if len(listed.Items) != 1 || !reflect.DeepEqual(listed.Items[0], winner) {
430						t.Fatalf("final GET %s items = %v, want exactly %v", target, listed.Items, winner)
431					}
432				}
433	
434				// Failed 409s, 400s and 200 retries consumed no order: the next
435				// brand-new identity takes order 2.
436				nextBody := singleRuleBody(raceNamespace, "after-race", raceLabel,
437					"egress", "allow", 53, 53, `{}`)
438				status, body, err := clientRequest(client, http.MethodPost,
439					server.URL+"/v1/net-policies", nextBody)
440				if err != nil {
441					t.Fatalf("POST next: %v", err)
442				}
443				if status != http.StatusCreated {
444					t.Fatalf("next status = %d, want 201: %s", status, string(body))
445				}
446				if got := decodeRecord(t, body); !reflect.DeepEqual(got, wantRecord(t, nextBody, 2, false)) {
447					t.Fatalf("next record = %v, want order 2 (lost and retried requests must not consume order)", got)
448				}
449			})
450		}
451	}
452	
453	// Two distinct policy names in one namespace sharing a label register at the
454	// same time: same direction, opposite actions, closed port intervals touching
455	// only at one endpoint. Both are 201; the one committed first gets order 1 and
456	// conflict=false, the other order 2 and conflict=true. Every filter returns
457	// both complete records in ascending order; retrying the original contents
458	// gives 200 without touching the flags, and a brand-new identity gets order 3.
459	func TestConcurrentHTTPTwoPoliciesConflictAndOrdering(t *testing.T) {
460		server, _ := newConcurrentTestServer(t)
461		client := &http.Client{Timeout: clientTimeout}
462	
463		// [80,100] and [100,200] intersect only at the closed endpoint 100.
464		denyBody := singleRuleBody("payments", "api-deny", "tier=backend",
465			"ingress", "deny", 80, 100, `{"mode": "enforce"}`)
466		allowBody := singleRuleBody("payments", "api-allow", "tier=backend",
467			"ingress", "allow", 100, 200, `{"mode": "enforce"}`)
468		bodyByName := map[string]string{"api-deny": denyBody, "api-allow": allowBody}
469	
470		start := make(chan struct{})
471		results := make(chan postOutcome, 2)
472		for _, body := range []string{denyBody, allowBody} {
473			go func(body string) {
474				<-start
475				status, raw, err := clientRequest(client, http.MethodPost,
476					server.URL+"/v1/net-policies", body)
477				results <- postOutcome{body: raw, status: status, err: err}
478			}(body)
479		}
480		close(start)
481	
482		storedByName := make(map[string]map[string]any, 2)
483		var first, second map[string]any
484		for range 2 {
485			result := <-results
486			if result.err != nil {
487				t.Fatalf("concurrent POST failed: %v", result.err)
488			}
489			if result.status != http.StatusCreated {
490				t.Fatalf("status = %d, want 201 for both distinct identities: %s",
491					result.status, string(result.body))
492			}
493			record := decodeRecord(t, result.body)
494			name, _ := record["name"].(string)
495			storedByName[name] = record
496			if first == nil || record["order"].(float64) < first["order"].(float64) {
497				second = first
498				first = record
499			} else {
500				second = record
501			}
502		}
503	
504		// Which name commits first is not prescribed; the returned order decides.
505		if first["order"] != float64(1) || first["conflict"] != false {
506			t.Fatalf("first committed = order %v conflict %v, want 1/false",
507				first["order"], first["conflict"])
508		}
509		if second["order"] != float64(2) || second["conflict"] != true {
510			t.Fatalf("second committed = order %v conflict %v, want 2/true",
511				second["order"], second["conflict"])
512		}
513		for order, record := range map[int64]map[string]any{1: first, 2: second} {
514			name, _ := record["name"].(string)
515			if _, known := bodyByName[name]; !known {
516				t.Fatalf("unexpected committed name %q", name)
517			}
518			want := wantRecord(t, bodyByName[name], order, order == 2)
519			if !reflect.DeepEqual(record, want) {
520				t.Fatalf("committed %s = %v, want the full submission with order %d and conflict=%v",
521					name, record, order, order == 2)
522			}
523		}
524	
525		want := []map[string]any{first, second}
526		for _, target := range []string{
527			server.URL + "/v1/net-policies?namespace=payments",
528			server.URL + "/v1/net-policies?label=tier%3Dbackend",
529			server.URL + "/v1/net-policies?namespace=payments&label=tier%3Dbackend",
530		} {
531			status, raw, err := clientRequest(client, http.MethodGet, target, "")
532			if err != nil {
533				t.Fatalf("GET %s: %v", target, err)
534			}
535			if status != http.StatusOK {
536				t.Fatalf("GET %s status = %d: %s", target, status, string(raw))
537			}
538			var body struct {
539				Items []map[string]any `json:"items"`
540			}
541			if err := json.Unmarshal(raw, &body); err != nil {
542				t.Fatalf("decode items: %v", err)
543			}
544			if !reflect.DeepEqual(body.Items, want) {
545				t.Fatalf("GET %s items = %v, want both complete records ascending by order",
546					target, body.Items)
547			}
548		}
549	
550		// Retry the original contents (one with reordered object members): 200 and
551		// the stored records, conflict flags included, come back untouched.
552		denyRetry := `{
553			"pluginParams": {"mode": "enforce"},
554			"rules": [{"ports": [80, 100], "action": "deny", "direction": "ingress"}],
555			"label": "tier=backend",
556			"name": "api-deny",
557			"namespace": "payments"
558		}`
559		for _, retry := range []struct {
560			name string
561			body string
562		}{
563			{"api-deny", denyRetry},
564			{"api-allow", allowBody},
565		} {
566			status, raw, err := clientRequest(client, http.MethodPost,
567				server.URL+"/v1/net-policies", retry.body)
568			if err != nil {
569				t.Fatalf("retry POST: %v", err)
570			}
571			if status != http.StatusOK {
572				t.Fatalf("retry status = %d, want 200: %s", status, string(raw))
573			}
574			if got := decodeRecord(t, raw); !reflect.DeepEqual(got, storedByName[retry.name]) {
575				t.Fatalf("retry record = %v, want unchanged original %v", got, storedByName[retry.name])
576			}
577		}
578	
579		// Retries consumed no order: a brand-new identity continues at order 3.
580		nextBody := singleRuleBody("payments", "api-next", "tier=backend",
581			"egress", "allow", 53, 53, `{}`)
582		status, raw, err := clientRequest(client, http.MethodPost,
583			server.URL+"/v1/net-policies", nextBody)
584		if err != nil {
585			t.Fatalf("POST next: %v", err)
586		}
587		if status != http.StatusCreated {
588			t.Fatalf("next status = %d, want 201: %s", status, string(raw))
589		}
590		if got := decodeRecord(t, raw); !reflect.DeepEqual(got, wantRecord(t, nextBody, 3, false)) {
